const BOOK: { name: string; difficulty: Difficulty; blurb: string; levels: LevelDef[] }[] = [
  { name: "Tutorial", difficulty: "Easy", blurb: "The rules, one at a time.", levels: TUTORIAL },
  { name: "Bent out of shape", difficulty: "Medium", blurb: "Hatches with corners, and less room to turn them.", levels: SHAPES },
  { name: "Cold snap", difficulty: "Medium", blurb: "Frozen hatches thaw only when enough chickens have dropped.", levels: ICE },
  { name: "Lock-up", difficulty: "Medium", blurb: "Padlocked hatches wait for the key.", levels: LOCKS },
  { name: "Good eggs", difficulty: "Medium", blurb: "An egg keeps its colour secret until a hatch slides up beside it.", levels: EGGS },
  { name: "Creaky floor", difficulty: "Medium", blurb: "Cracked boards hold for one crossing. After that, there is no way back.", levels: CRACKS },
  { name: "Odd birds", difficulty: "Medium", blurb: "A white chicken will drop down any hatch. Choose whose room it takes.", levels: WHITES },
  { name: "In step", difficulty: "Medium", blurb: "Two hatches on a chain slide together, or not at all.", levels: CHAINS },
  { name: "Thin ice", difficulty: "Medium", blurb: "Cracked boards and frozen hatches. Wait for the thaw, but not on the wrong board.", levels: THAW },
  { name: "Mystery guests", difficulty: "Medium", blurb: "White chickens and eggs. Some eggs hold white chickens, and some white chickens are spoken for.", levels: GUESTS },
  { name: "Chain of custody", difficulty: "Medium", blurb: "Chained hatches and padlocks. One locked hatch holds its partner still too.", levels: CUSTODY },
  { name: "Tangled", difficulty: "Medium", blurb: "Chained hatches with corners. Two awkward shapes, one move at a time.", levels: TANGLED },
  { name: "Skid row", difficulty: "Medium", blurb: "Slippery floor: once a hatch is on it, it can’t stop until something stops it.", levels: SLIPPERY },
  { name: "Shove off", difficulty: "Medium", blurb: "Crates go where they’re shoved, a square at a time. Shove one into a corner and there it stays.", levels: CRATES },
  { name: "Spin doctor", difficulty: "Medium", blurb: "Turntables swing a hatch a quarter turn. Come at them from the side that leaves room to turn.", levels: TURNTABLES },
  { name: "Down the rabbit hole", difficulty: "Medium", blurb: "A one-square hatch can take the burrow from one end to the other. Bigger ones have to go round.", levels: BURROWS },
  { name: "Flight risk", difficulty: "Medium", blurb: "Skittish chickens hop away from a hatch that stops beside them. Herd them into a corner.", levels: SKITTISH },
  { name: "Opposite numbers", difficulty: "Medium", blurb: "Mirrored hatches slide opposite ways. Line one up and the other wanders off.", levels: MIRRORS },
  { name: "Doorkeepers", difficulty: "Medium", blurb: "Every lever flips every door. Cross one at the right moment, and not again.", levels: LEVERS },
  { name: "Running ragged", difficulty: "Medium", blurb: "Tired hatches can only be picked up so many times. Make each move count.", levels: TIRED },
  { name: "Mind your manners", difficulty: "Medium", blurb: "Numbered chickens go in turn. Leave number 3 for later, even when it’s right there.", levels: ORDERLY },
  { name: "Over the fence", difficulty: "Medium", blurb: "Fences run along the edges of squares, and nothing gets over them.", levels: FENCES },
  { name: "Two up", difficulty: "Medium", blurb: "Chickens sitting on chickens. Take the top one, and come back for the other.", levels: STACKS },
  { name: "Stuck in the mud", difficulty: "Medium", blurb: "Slide onto mud and that hatch is stuck until another has moved. Choose where to stop.", levels: MUDDY },
  { name: "Small enough", difficulty: "Medium", blurb: "Narrow bridges only take hatches of one or two squares. The big ones go the long way round.", levels: BRIDGES_NARROW },
  { name: "Fox watch", difficulty: "Medium", blurb: "A fox closes in on the chickens, a square every move. Be quick, or stand a hatch in its way.", levels: FOXES },
  { name: "Belt up", difficulty: "Medium", blurb: "Conveyor belts carry chickens along a square every move, into reach or out of it.", levels: BELTS },
  { name: "Follow me", difficulty: "Medium", blurb: "Curious chickens follow a hatch that slides away from them. Lead them where they need to be.", levels: CURIOUS },
  { name: "Changing colours", difficulty: "Medium", blurb: "Some chickens swap colour every move. Arrive when they’re the right one.", levels: FICKLE },
  { name: "Sound asleep", difficulty: "Medium", blurb: "Sleeping chickens won’t go down a hatch. Stop a hatch beside one to wake it, then come back.", levels: SLEEPERS },
  { name: "Animal magnetism", difficulty: "Medium", blurb: "A magnet pulls every hatch in line with it one square closer, each move.", levels: MAGNETS },
  { name: "Cutting edge", difficulty: "Medium", blurb: "Slide a two-square hatch across a blade and it splits into two small ones.", levels: BLADES },
  { name: "Short fuse", difficulty: "Medium", blurb: "Slide onto a bomb and it blows the hay bales around it away.", levels: BOMBS },
  { name: "The whole flock", difficulty: "Hard", blurb: "Bends, ice, padlocks and eggs, all at once.", levels: FLOCK },
  { name: "Free range", difficulty: "Hard", blurb: "No tricks. Plain hatches, crowded yards, and a long way round.", levels: RANGE },
  { name: "Bent double", difficulty: "Hard", blurb: "More corners than floor. Every turn has to be planned.", levels: TWISTS },
  { name: "Permafrost", difficulty: "Hard", blurb: "Thaw the wrong hatch first and the rest stay frozen.", levels: FROST },
  { name: "Maximum security", difficulty: "Hard", blurb: "The key is a long way off, and the padlocked hatch is in the way.", levels: CELLS },
  { name: "Three-ring coop", difficulty: "Hard", blurb: "Cracked boards, white chickens and chains, all in the same yard.", levels: MEDLEY },
  { name: "Wet paint", difficulty: "Hard", blurb: "Slide through a puddle and a hatch changes colour, and with it which chickens it takes.", levels: PAINTED },
  { name: "Gatekeeper", difficulty: "Hard", blurb: "A gate opens only while a hatch stands on a pressure plate. Someone has to hold the door.", levels: GATES },
  { name: "One way only", difficulty: "Hard", blurb: "Arrows can only be crossed the way they point. Every detour costs.", levels: ONE_WAY },
  { name: "Hold the line", difficulty: "Hard", blurb: "Gates and chained hatches. A chained pair can hold the door together, or get stuck in it together.", levels: TANDEM },
  { name: "Burnt bridges", difficulty: "Hard", blurb: "One-way squares and cracked boards. Cross in the wrong order and the way home is gone.", levels: BRIDGES },
  { name: "Colour me surprised", difficulty: "Hard", blurb: "Paint and eggs. Crack an egg before you choose a coat.", levels: DYED },
  { name: "Turning point", difficulty: "Hard", blurb: "Turntables and a yard full of bent hatches. Which way a hatch faces decides where it can go next.", levels: TURNSTILES },
  { name: "Goods in", difficulty: "Hard", blurb: "Crates and padlocks. The key is behind the crates, or the crates are behind the lock.", levels: LOCKED_CRATES },
  { name: "Pick and mix", difficulty: "Hard", blurb: "The newest pieces in twos, and twice all five at once.", levels: PICK_MIX },
  { name: "Stuck with the fox", difficulty: "Hard", blurb: "Mud ends a move, and every move lets the fox take another step.", levels: FOX_MUD },
  { name: "Factory fencing", difficulty: "Hard", blurb: "Belts carry hatches along until a fence says otherwise.", levels: BELT_FENCE },
  { name: "Smoke and mirrors", difficulty: "Hard", blurb: "Mirrored pairs and levers. One of the pair pulls the lever whether you meant it or not.", levels: MIRROR_LEVER },
  { name: "Chain of command", difficulty: "Hard", blurb: "A pecking order, and chickens sitting on chickens. The next in line may be underneath.", levels: ORDER_STACK },
  { name: "Nosy neighbours", difficulty: "Hard", blurb: "Curious chickens follow you about, and the bridges are only one hatch wide.", levels: BRIDGE_CURIOUS },
  { name: "Muddied waters", difficulty: "Hard", blurb: "Chickens that change colour every move, and mud that ends your move early.", levels: FICKLE_MUD },
  { name: "Hard-boiled", difficulty: "Expert", blurb: "Bends, ice, padlocks and eggs, all in one coop. Thirty moves is a good day.", levels: BOILED },
  { name: "The workshop", difficulty: "Expert", blurb: "Paint, gates and one-way floors in one yard. Plan who holds the door, and who changes coats.", levels: WORKSHOP },
  { name: "Big freeze", difficulty: "Expert", blurb: "Frozen hatches, bent hatches and gates. The thaw comes in its own time, and the door won't wait.", levels: FREEZE },
  { name: "Safe cracking", difficulty: "Expert", blurb: "Padlocks, paint and eggs. Find the key, choose the colour, and don't trust a shell.", levels: VAULT },
];

let count = 0;
export const CHAPTERS: Chapter[] = BOOK.map((c) => ({ name: c.name, difficulty: c.difficulty, blurb: c.blurb, levels: c.levels.map((d) => parseLevel(d, count++, c.name)) }));

/** Every level in order. */
export const LEVELS: Level[] = CHAPTERS.flatMap((c) => c.levels);
